#!/usr/bin/env bash
# Question 12: Identity of kubeconfig user ${Q12_USER}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/kc/identity
mkdir -p /opt/course/kc/identity
chown -R ubuntu:ubuntu /opt/course
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
sign() {
  openssl genrsa -out "$work/$1.key" 2048 2>/dev/null
  openssl req -new -key "$work/$1.key" -subj "$2" -out "$work/$1.csr" 2>/dev/null
  openssl x509 -req -in "$work/$1.csr" -CA /etc/kubernetes/pki/ca.crt -CAkey /etc/kubernetes/pki/ca.key -CAserial "$work/ca.srl" -CAcreateserial -days "$3" -out "$work/$1.crt" 2>/dev/null
}
kc() { local f=$1; shift; kubectl --kubeconfig "$f" config "$@" >/dev/null; }
server=$(kubectl config view --minify -o jsonpath='{.clusters[0].cluster.server}')
f=/opt/course/kc/identity/kubeconfig
read -r g1 g2 < <(shuf -e developers auditors on-call platform release-managers -n 2 | xargs)
sign target "/CN=$(shuf -e alex.kim jo.park sam.ruiz lee.chen ana.silva mia.wong raj.patel tom.berg -n 1)/O=$g1/O=$g2" "$(shuf -i 30-400 -n 1)"
sign bot "/CN=deploy-bot/O=ci" 365
sign viewer "/CN=$(shuf -e alex.kim jo.park sam.ruiz lee.chen ana.silva mia.wong raj.patel tom.berg -n 1)/O=readonly" "$(shuf -i 30-400 -n 1)"
kc "$f" set-cluster kubernetes --server="$server" --certificate-authority=/etc/kubernetes/pki/ca.crt --embed-certs=true
kc "$f" set-credentials "deploy-bot" --client-certificate="$work/bot.crt" --client-key="$work/bot.key" --embed-certs=true
kc "$f" set-credentials "${Q12_USER}" --client-certificate="$work/target.crt" --client-key="$work/target.key" --embed-certs=true
kc "$f" set-credentials "viewer" --client-certificate="$work/viewer.crt" --client-key="$work/viewer.key" --embed-certs=true
kc "$f" set-context ci-deploy --cluster=kubernetes --user=deploy-bot --namespace=ci
kc "$f" set-context "${Q12_CTX}" --cluster=kubernetes --user="${Q12_USER}" --namespace="${Q12_NS}"
kc "$f" set-context read-only --cluster=kubernetes --user=viewer
kc "$f" use-context ci-deploy
cp "/opt/course/kc/identity/kubeconfig" "/var/tmp/cka-kc-identity-kubeconfig"
chmod 600 "/var/tmp/cka-kc-identity-kubeconfig"
chown -R ubuntu:ubuntu /opt/course/kc
: "${Q12_USER}" "${Q12_CTX}" "${Q12_NS}"
